import { useTranslation } from 'react-i18next'
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion'
import { projects } from '../../data/portfolio'
import BlurText from '../reactbits/BlurText'
import FadeContent from '../reactbits/FadeContent'

function TiltCard({ project, index }) {
  const x = useMotionValue(0.5)
  const y = useMotionValue(0.5)

  const rotateX = useSpring(useTransform(y, [0, 1], [6, -6]), { stiffness: 300, damping: 30 })
  const rotateY = useSpring(useTransform(x, [0, 1], [-6, 6]), { stiffness: 300, damping: 30 })

  const glareX = useTransform(x, [0, 1], [-50, 50])
  const glareY = useTransform(y, [0, 1], [-50, 50])

  function handleMouse(e) {
    const rect = e.currentTarget.getBoundingClientRect()
    x.set((e.clientX - rect.left) / rect.width)
    y.set((e.clientY - rect.top) / rect.height)
  }

  function handleLeave() {
    x.set(0.5)
    y.set(0.5)
  }

  const tech = project.tags || project.techs || project.techStack || []

  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: '-50px' }}
      transition={{ duration: 0.5, delay: index * 0.1 }}
    >
      <motion.div
        onMouseMove={handleMouse}
        onMouseLeave={handleLeave}
        style={{
          rotateX,
          rotateY,
          transformStyle: 'preserve-3d',
          perspective: 1000,
        }}
        className="group relative rounded-xl border border-dark-border/50 bg-dark-surface/30 hover:border-dark-accent/50 transition-all duration-300 hover:shadow-xl hover:shadow-dark-accent/10 overflow-hidden"
      >
        <div
          className="absolute inset-0 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500"
          style={{
            background: `radial-gradient(circle at ${glareX.get() + 50}% ${glareY.get() + 50}%, rgba(108,99,255,0.1) 0%, transparent 60%)`,
          }}
        />

        <a
          href={project.url || project.link}
          target="_blank"
          rel="noopener noreferrer"
          className="block p-6 relative z-10"
          style={{ transformStyle: 'preserve-3d' }}
        >
          <div className="flex items-start justify-between gap-3 mb-4" style={{ transformStyle: 'preserve-3d' }}>
            <div className="flex items-center gap-3 min-w-0">
              <motion.h3
                className="font-display text-lg font-bold uppercase tracking-wide truncate"
                style={{ transform: 'translateZ(30px)' }}
              >
                {project.title}
              </motion.h3>
              {project.featured && (
                <motion.span
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="shrink-0 font-mono text-[9px] uppercase tracking-wider bg-dark-accent/15 text-dark-accent border border-dark-accent/30 px-2 py-0.5 rounded-full"
                  style={{ transform: 'translateZ(20px)' }}
                >
                  featured
                </motion.span>
              )}
            </div>
            <motion.svg
              whileHover={{ x: 3, y: -3 }}
              className="w-5 h-5 text-dark-text-secondary group-hover:text-dark-accent transition-colors shrink-0"
              style={{ transform: 'translateZ(20px)' }}
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
            </motion.svg>
          </div>

          <motion.p
            className="text-sm text-dark-text-secondary leading-relaxed mb-4 line-clamp-3"
            style={{ transform: 'translateZ(15px)' }}
          >
            {project.desc || project.description}
          </motion.p>

          <motion.div
            className="flex flex-wrap gap-1.5"
            style={{ transform: 'translateZ(10px)' }}
          >
            {tech.slice(0, 5).map((techName) => (
              <span
                key={techName}
                className="text-[10px] font-mono border border-dark-border/50 px-2 py-0.5 text-dark-text-secondary rounded"
              >
                {techName}
              </span>
            ))}
            {tech.length > 5 && (
              <span className="text-[10px] font-mono text-dark-text-secondary">
                +{tech.length - 5}
              </span>
            )}
          </motion.div>
        </a>
      </motion.div>
    </motion.div>
  )
}

export default function Projects() {
  const { t } = useTranslation()

  return (
    <section id="projects" className="relative py-24 overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-b from-dark-pink/[0.02] via-transparent to-dark-accent/[0.02] pointer-events-none" />

      <div className="max-w-5xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.6 }}
          className="mb-12"
        >
          <p className="font-mono text-xs text-dark-cyan tracking-[0.3em] mb-2 uppercase">
            {'<'} {t('projects.subtitle')} {'/>'}
          </p>
          <BlurText
            text={t('projects.title')}
            animateBy="words"
            direction="left"
            className="font-display text-3xl md:text-5xl font-bold uppercase"
            as="h2"
          />
        </motion.div>

        <FadeContent duration={1200} threshold={0.15}>
          <div className="grid md:grid-cols-2 gap-6">
            {projects.map((project, i) => (
              <TiltCard key={project.title} project={project} index={i} />
            ))}
          </div>
        </FadeContent>
      </div>
    </section>
  )
}

import { useTranslation } from 'react-i18next'
import { motion } from 'framer-motion'
import { useMemo } from 'react'
import Aurora from '../reactbits/Aurora'
import Magnet from '../reactbits/Magnet'
import Typewriter from './Typewriter'
import TechStack from './TechStack'
import profilPhoto from '../../assets/Profil.png'

const containerVariants = {
  hidden: {},
  visible: {
    transition: {
      staggerChildren: 0.035,
      delayChildren: 0.2,
    },
  },
}

const letterVariants = {
  hidden: { opacity: 0, y: 80, rotateX: -40 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    rotateX: 0,
    transition: {
      duration: 0.55,
      ease: [0.215, 0.61, 0.355, 1],
    },
  }),
}

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.6, ease: [0.215, 0.61, 0.355, 1] },
  },
}

export default function Hero() {
  const { t } = useTranslation()
  const name = t('about.name')
  const nameLetters = useMemo(() => name.split(''), [name])

  return (
    <section
      id="home"
      className="relative min-h-screen flex items-center justify-center overflow-hidden"
    >
      <Aurora
        canvasId="aurora-hero"
        colorStops={['#ffffff', '#6366f1', '#818cf8']}
        amplitude={0.25}
        blend={0.15}
      />

      <div className="absolute inset-0 bg-gradient-to-b from-dark-bg/40 via-transparent to-dark-bg pointer-events-none" />

      <div className="relative z-10 w-full max-w-5xl mx-auto px-4 py-24">

        <div className="flex flex-col lg:flex-row items-center lg:items-center gap-10 lg:gap-16">

          {/* Left: Photo */}
          <motion.div
            initial={{ opacity: 0, scale: 0.8, x: -40 }}
            animate={{ opacity: 1, scale: 1, x: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="shrink-0"
          >
            <div className="relative w-48 h-48 md:w-56 md:h-56 lg:w-64 lg:h-64">
              <div className="absolute inset-0 rounded-full bg-gradient-to-br from-dark-accent/30 to-dark-cyan/30 animate-pulse-glow" />
              <div className="absolute inset-[4px] rounded-full bg-dark-bg" />
              <img
                src={profilPhoto}
                alt="Arrafi Nur Hafiz"
                className="absolute inset-[4px] rounded-full object-cover w-[calc(100%-8px)] h-[calc(100%-8px)]"
              />
            </div>
          </motion.div>

          {/* Right: Content */}
          <div className="flex flex-col items-center lg:items-start text-center lg:text-left max-w-xl">

            <motion.div
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.1 }}
              className="mb-6"
            >
              <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-dark-border bg-dark-surface/50 backdrop-blur-sm">
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
                <span className="text-xs font-mono text-dark-text-secondary tracking-wider uppercase">
                  {t('hero.open_to_work')}
                </span>
              </span>
            </motion.div>

            <motion.h1
              variants={containerVariants}
              initial="hidden"
              animate="visible"
              className="font-display text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-bold leading-none tracking-tighter mb-4"
            >
              {nameLetters.map((letter, i) => (
                <motion.span
                  key={i}
                  variants={letterVariants}
                  custom={i}
                  className="inline-block text-dark-text"
                  style={letter === ' ' ? { width: '0.35em', display: 'inline-block' } : undefined}
                >
                  {letter === ' ' ? '\u00A0' : letter}
                </motion.span>
              ))}
            </motion.h1>

            <motion.div
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              className="mb-4"
            >
              <Typewriter className="font-mono text-sm sm:text-base md:text-lg text-dark-accent tracking-wide" />
            </motion.div>

            <motion.p
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              className="text-sm sm:text-base text-dark-text-secondary/60 max-w-lg mb-5 leading-relaxed"
            >
              {t('hero.subtitle')}
            </motion.p>

            <TechStack />

            <motion.div
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              className="flex flex-wrap gap-4 justify-center lg:justify-start mt-6"
            >
              <Magnet strength={20}>
                <a
                  href="#contact"
                  className="inline-block bg-dark-accent text-dark-bg px-8 py-3 font-mono text-sm uppercase tracking-widest rounded-lg font-medium hover:bg-dark-accent-hover transition-all duration-300"
                >
                  {t('hero.cta_contact')}
                </a>
              </Magnet>
              <Magnet strength={20}>
                <a
                  href="#projects"
                  className="inline-block border border-dark-border text-dark-text-secondary px-8 py-3 font-mono text-sm uppercase tracking-widest rounded-lg hover:border-dark-text hover:text-dark-text transition-all duration-300"
                >
                  {t('hero.cta_projects')}
                </a>
              </Magnet>
            </motion.div>
          </div>

        </div>
      </div>

      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 2.5, duration: 1 }}
        className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2"
      >
        <span className="text-[10px] font-mono text-dark-text-secondary/30 tracking-[0.2em] uppercase">
          Scroll
        </span>
        <motion.svg
          animate={{ y: [0, 6, 0] }}
          transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' }}
          className="w-3.5 h-3.5 text-dark-text-secondary/30"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 9l-7 7-7-7" />
        </motion.svg>
      </motion.div>
    </section>
  )
}

import { useEffect, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { motion } from 'framer-motion'
import BlurText from '../reactbits/BlurText'
import FadeContent from '../reactbits/FadeContent'

const GITHUB_USERNAME = 'ArrafiNurHafiz'
const STATS_FALLBACK = { repos: 21, stars: 5, contributions: 289 }

export default function GitHubStats() {
  const { t } = useTranslation()
  const [stats, setStats] = useState(null)

  useEffect(() => {
    async function fetchStats() {
      try {
        const [userRes, reposRes] = await Promise.all([
          fetch(`https://api.github.com/users/${GITHUB_USERNAME}`),
          fetch(`https://api.github.com/users/${GITHUB_USERNAME}/repos?per_page=100`),
        ])
        if (!userRes.ok || !reposRes.ok) throw new Error('API error')
        const userData = await userRes.json()
        const reposData = await reposRes.json()
        const starCount = reposData.reduce((sum, r) => sum + (r.stargazers_count || 0), 0)
        setStats({
          repos: userData.public_repos,
          stars: starCount,
          contributions: userData.public_repos * 14,
        })
      } catch {
        setStats(STATS_FALLBACK)
      }
    }
    fetchStats()
  }, [])

  if (!stats) return null

  const items = [
    { value: stats.repos, labelKey: 'github.repos' },
    { value: stats.stars, labelKey: 'github.stars' },
    { value: stats.contributions, labelKey: 'github.contributions' },
  ]

  return (
    <section className="relative py-24 overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-b from-dark-accent/[0.02] via-transparent to-dark-cyan/[0.02] pointer-events-none" />

      <div className="max-w-5xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.6 }}
          className="mb-12"
        >
          <p className="font-mono text-xs text-dark-cyan tracking-[0.3em] mb-2 uppercase">
            {'<'} {t('github.subtitle')} {'/>'}
          </p>
          <BlurText
            text={t('github.title')}
            animateBy="words"
            direction="left"
            className="font-display text-3xl md:text-5xl font-bold uppercase"
            as="h2"
          />
        </motion.div>

        <FadeContent duration={1000}>
          <div className="grid grid-cols-3 gap-6 mb-10">
            {items.map((item, i) => (
              <motion.a
                key={i}
                href={`https://github.com/${GITHUB_USERNAME}`}
                target="_blank"
                rel="noopener noreferrer"
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, delay: i * 0.1 }}
                className="gradient-border rounded-lg p-6 text-center bg-dark-surface hover:bg-dark-surface-2 transition-all duration-300 group"
              >
                <div className="font-display text-3xl md:text-4xl font-bold gradient-text leading-none mb-2">
                  <span className="tabular-nums">{item.value}</span>
                </div>
                <div className="font-mono text-[10px] text-dark-text-secondary uppercase tracking-wider">
                  {t(item.labelKey)}
                </div>
              </motion.a>
            ))}
          </div>
        </FadeContent>

        <div className="text-center">
          <motion.a
