import { useState, useEffect } from 'react'
import { useParams, Link } from 'react-router-dom'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { useTranslation } from 'react-i18next'
import { motion } from 'framer-motion'

const POSTS = [
  { slug: 'multi-node-monitoring', file: () => import('./posts/multi-node-monitoring.md') },
  { slug: 'vuln-scanner', file: () => import('./posts/vuln-scanner.md') },
  { slug: 'arisan-chain', file: () => import('./posts/arisan-chain.md') },
  { slug: 'curiosity-engine', file: () => import('./posts/curiosity-engine.md') },
]

function parseFrontmatter(raw) {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/)
  if (!match) return { frontmatter: {}, content: raw }

  const fm = {}
  match[1].split('\n').forEach((line) => {
    const sep = line.indexOf(':')
    if (sep > 0) {
      const key = line.slice(0, sep).trim()
      let val = line.slice(sep + 1).trim()
      if (val.startsWith('[') && val.endsWith(']')) {
        val = JSON.parse(val.replace(/'/g, '"'))
      }
      fm[key] = val
    }
  })
  return { frontmatter: fm, content: match[2] }
}

export default function BlogPost() {
  const { slug } = useParams()
  const { t } = useTranslation()
  const [post, setPost] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const entry = POSTS.find((p) => p.slug === slug)
    if (!entry) {
      setLoading(false)
      return
    }

    entry
      .file()
      .then((mod) => {
        const raw = mod.default || mod
        const { frontmatter, content } = parseFrontmatter(raw)
        setPost({ frontmatter, content })
        setLoading(false)
      })
      .catch(() => setLoading(false))
  }, [slug])

  if (loading) {
    return (
      <div className="min-h-screen bg-dark-bg flex items-center justify-center">
        <div className="font-mono text-dark-text-secondary">
          <span className="animate-pulse">Loading...</span>
        </div>
      </div>
    )
  }

  if (!post) {
    return (
      <div className="min-h-screen bg-dark-bg flex items-center justify-center">
        <div className="text-center space-y-4">
          <p className="font-mono text-dark-text-secondary">Post not found</p>
          <Link to="/#blog" className="font-mono text-sm text-dark-accent hover:underline">
            ← Back to blog
          </Link>
        </div>
      </div>
    )
  }

  const fm = post.frontmatter
  const tags = fm.tags || []

  return (
    <div className="min-h-screen bg-dark-bg">
      <div className="max-w-3xl mx-auto px-4 py-24">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <Link
            to="/#blog"
            className="inline-flex items-center gap-2 font-mono text-sm text-dark-text-secondary hover:text-dark-accent transition-colors mb-8"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            {t('blog.read_more')}
          </Link>

          <div className="mb-8">
            <div className="flex flex-wrap gap-2 mb-4">
              {tags.map((tag) => (
                <span
                  key={tag}
                  className="font-mono text-[10px] border border-dark-border/40 px-2 py-0.5 rounded text-dark-text-secondary"
                >
                  {tag}
                </span>
              ))}
            </div>
            <span className="font-mono text-xs text-dark-cyan">Published: {fm.date}</span>
          </div>

          <article className="prose prose-invert max-w-none
            prose-headings:font-display prose-headings:text-dark-text
            prose-h1:text-3xl prose-h1:font-bold prose-h1:mb-6
            prose-h2:text-xl prose-h2:font-semibold prose-h2:mt-10 prose-h2:mb-4
            prose-h3:text-lg prose-h3:mt-8 prose-h3:mb-3
            prose-p:text-dark-text-secondary prose-p:leading-relaxed prose-p:mb-4
            prose-a:text-dark-accent prose-a:no-underline hover:prose-a:underline
            prose-strong:text-dark-text
            prose-code:text-dark-cyan prose-code:bg-dark-surface/50 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded prose-code:text-xs
            prose-pre:bg-dark-surface/50 prose-pre:border prose-pre:border-dark-border/30 prose-pre:rounded-lg
            prose-li:text-dark-text-secondary
            prose-th:text-dark-text
            prose-td:text-dark-text-secondary
            prose-hr:border-dark-border/30
            prose-blockquote:border-dark-accent/40 prose-blockquote:text-dark-text-secondary
          ">
            <h1 className="text-3xl md:text-4xl font-display font-bold mb-2">{fm.title}</h1>
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{post.content}</ReactMarkdown>
          </article>
        </motion.div>
      </div>
    </div>
  )
}

