import { useTranslation } from 'react-i18next'
import { motion } from 'framer-motion'
import { experience } from '../../data/portfolio'
import BlurText from '../reactbits/BlurText'

function TimelineDot({ delay }) {
  return (
    <div className="absolute -left-[11px] top-1 z-10">
      <motion.div
        initial={{ scale: 0 }}
        whileInView={{ scale: 1 }}
        viewport={{ once: true }}
        transition={{ delay: delay + 0.2, type: 'spring', stiffness: 200 }}
        className="relative w-[22px] h-[22px] rounded-full border-2 border-dark-accent bg-dark-bg"
      >
        <div className="absolute inset-1 rounded-full bg-dark-accent shadow-lg shadow-dark-accent/50" />
        <motion.div
          className="absolute inset-[-4px] rounded-full border border-dark-accent/30"
          animate={{ scale: [1, 1.3, 1], opacity: [0.3, 0, 0.3] }}
          transition={{ duration: 2.5, repeat: Infinity, ease: 'easeInOut' }}
        />
      </motion.div>
    </div>
  )
}

function SkillTag({ skill, color }) {
  return (
    <span
      className="text-[10px] font-mono border px-2 py-0.5 rounded transition-all duration-300"
      style={{
        borderColor: `${color}40`,
        color: `${color}cc`,
      }}
    >
      {skill}
    </span>
  )
}

const cardColors = ['#6C63FF', '#00D4FF', '#FF6B9D']

export default function Experience() {
  const { t } = useTranslation()

  return (
    <section id="experience" className="relative py-24 overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-b from-dark-accent/[0.02] via-transparent to-dark-cyan/[0.02] pointer-events-none" />

      <div className="max-w-5xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.6 }}
          className="mb-12"
        >
          <p className="font-mono text-xs text-dark-cyan tracking-[0.3em] mb-2 uppercase">
            {'<'} {t('experience.subtitle')} {'/>'}
          </p>
          <BlurText
            text={t('experience.title')}
            animateBy="words"
            direction="left"
            className="font-display text-3xl md:text-5xl font-bold uppercase"
            as="h2"
          />
        </motion.div>

        <div className="relative pl-8">
          <motion.div
            initial={{ scaleY: 0 }}
            whileInView={{ scaleY: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 1.2, ease: 'easeInOut' }}
            className="absolute left-1 top-0 bottom-0 w-[2px] origin-top"
            style={{
              background: 'linear-gradient(to bottom, #6C63FF, #00D4FF, #FF6B9D)',
              boxShadow: '0 0 12px rgba(108,99,255,0.3), inset 0 0 6px rgba(108,99,255,0.1)',
            }}
          />

          {experience.map((item, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, x: -30 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true, margin: '-50px' }}
              transition={{ duration: 0.5, delay: i * 0.2 }}
              className="relative pb-10 last:pb-0"
            >
              <TimelineDot delay={i * 0.2} />

              <div className="ml-4 rounded-xl overflow-hidden p-[1px] transition-all duration-500 hover:shadow-lg hover:shadow-dark-accent/10"
                style={{
                  background: `linear-gradient(135deg, ${cardColors[i % 3]}40, transparent 60%, ${cardColors[(i + 1) % 3]}20)`,
                }}
              >
                <div className="rounded-[calc(0.75rem-1px)] bg-dark-surface/40 backdrop-blur-sm p-5 h-full transition-all duration-300">
                  <div className="flex flex-wrap items-baseline justify-between gap-2 mb-2">
                    <h3 className="font-display text-base font-bold uppercase tracking-wide text-dark-text">
                      {item.role || item.title}
                    </h3>
                    <span className="font-mono text-[11px] text-dark-cyan tracking-wide">
                      {'>'} {item.period}
                    </span>
                  </div>

                  <p className="font-mono text-xs uppercase tracking-wider mb-3"
                    style={{ color: cardColors[i % 3] }}
                  >
                    {item.org || item.company}
                  </p>

                  <ul className="space-y-1.5">
                    {(item.highlights || item.descriptions || []).map((desc, j) => (
                      <motion.li
                        key={j}
                        initial={{ opacity: 0, x: -10 }}
                        whileInView={{ opacity: 1, x: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: i * 0.2 + j * 0.1 + 0.2 }}
                        className="flex items-start gap-2 text-sm text-dark-text-secondary"
                      >
                        <span className="shrink-0 mt-0.5 font-mono" style={{ color: cardColors[i % 3] }}>&rsaquo;</span>
                        {desc}
                      </motion.li>
                    ))}
                  </ul>

                  {item.skills && item.skills.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mt-4 border-t border-dark-border/20 pt-3">
                      {item.skills.map((skill) => (
                        <SkillTag key={skill} skill={skill} color={cardColors[i % 3]} />
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { useLocation, useNavigate } from 'react-router-dom'
import { AnimatePresence, motion } from 'framer-motion'
import Magnet from '../reactbits/Magnet'

const links = [
  { key: 'home', href: '#home' },
  { key: 'about', href: '#about' },
  { key: 'skills', href: '#skills' },
  { key: 'projects', href: '#projects' },
  { key: 'experience', href: '#experience' },
  { key: 'github', href: '#github' },
  { key: 'blog', href: '#blog' },
  { key: 'contact', href: '#contact' },
]

const sectionIds = links.map(l => l.href.slice(1))

export default function Navbar({ language, setLanguage }) {
  const { t, i18n } = useTranslation()
  const location = useLocation()
  const navigate = useNavigate()
  const [mobileOpen, setMobileOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)
  const [activeId, setActiveId] = useState('home')

  const isHomePage = location.pathname === '/'

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20)
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  useEffect(() => {
    if (!isHomePage) return
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setActiveId(entry.target.id)
          }
        }
      },
      { rootMargin: '-40% 0px -55% 0px' }
    )
    sectionIds.forEach((id) => {
      const el = document.getElementById(id)
      if (el) observer.observe(el)
    })
    return () => observer.disconnect()
  }, [isHomePage])

  const handleNavClick = (href, e) => {
    e.preventDefault()
    setMobileOpen(false)
    if (!isHomePage) {
      navigate(href)
    } else {
      const el = document.getElementById(href.slice(1))
      if (el) el.scrollIntoView({ behavior: 'smooth' })
    }
  }

  const isActive = (href) => isHomePage && activeId === href.slice(1)

  const toggleLang = useCallback(() => {
    const next = language === 'en' ? 'id' : 'en'
    setLanguage(next)
    i18n.changeLanguage(next)
  }, [language, setLanguage, i18n])

  return (
    <>
      <nav
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
          scrolled
            ? 'bg-dark-bg/80 backdrop-blur-xl border-b border-dark-border/30'
            : 'bg-transparent'
        }`}
      >
        <div className="max-w-6xl mx-auto px-6">
          <div className="flex items-center justify-between h-16 md:h-20">
            <a href="#home" onClick={(e) => handleNavClick('#home', e)} className="font-display font-bold text-xl tracking-widest text-dark-accent">
              ARRAFI
            </a>

            <div className="hidden md:flex items-center gap-1">
              {links.map(({ key, href }) => (
                <a
                  key={key}
                  href={href}
                  onClick={(e) => handleNavClick(href, e)}
                  className={`relative px-3 py-2 text-sm font-mono transition-colors duration-300 ${
                    isActive(href)
                      ? 'text-dark-accent'
                      : 'text-dark-text-secondary hover:text-dark-text'
                  }`}
                >
                  {t(`nav.${key}`)}
                  {isActive(href) && (
                    <motion.span
                      layoutId="nav-indicator"
                      className="absolute -bottom-0.5 left-1/2 -translate-x-1/2 w-1 h-1 rounded-full bg-dark-accent"
                      transition={{ type: 'spring', stiffness: 500, damping: 35 }}
                    />
                  )}
                </a>
              ))}
              <div className="ml-4 pl-4 border-l border-dark-border/50">
                <button
                  onClick={toggleLang}
                  className="px-3 py-1.5 text-xs font-mono border border-dark-border/50 text-dark-text-secondary hover:text-dark-accent hover:border-dark-accent/50 transition-all duration-300 rounded-full"
                >
                  {language === 'en' ? 'ID' : 'EN'}
                </button>
              </div>
