            <button
              className="md:hidden relative w-8 h-8 flex items-center justify-center text-dark-text-secondary hover:text-dark-accent transition-colors"
              onClick={() => setMobileOpen(!mobileOpen)}
              aria-label={mobileOpen ? 'Close menu' : 'Open menu'}
            >
              <span className="sr-only">Menu</span>
              <div className="w-5 h-4 relative flex flex-col justify-between">
                <span className={`block h-px w-full bg-current transition-all duration-300 ${mobileOpen ? 'rotate-45 translate-y-[7px]' : ''}`} />
                <span className={`block h-px w-full bg-current transition-all duration-300 ${mobileOpen ? 'opacity-0' : ''}`} />
                <span className={`block h-px w-full bg-current transition-all duration-300 ${mobileOpen ? '-rotate-45 -translate-y-[7px]' : ''}`} />
              </div>
            </button>
          </div>
        </div>
      </nav>

      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', stiffness: 300, damping: 30 }}
            className="fixed top-0 right-0 bottom-0 z-40 w-72 bg-dark-bg/95 backdrop-blur-2xl border-l border-dark-border/30 md:hidden"
          >
            <div className="flex flex-col justify-center h-full px-8 gap-2">
              {links.map(({ key, href }, i) => (
                <motion.a
                  key={key}
                  href={href}
                  onClick={(e) => handleNavClick(href, e)}
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: i * 0.05 }}
                  className={`text-2xl font-display py-2 transition-colors ${
                    isActive(href)
