import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'

export default function Loader({ onComplete }) {
  const { t } = useTranslation()
  const [msgIndex, setMsgIndex] = useState(-1)
  const [visible, setVisible] = useState(true)

  const messages = [
    t('loader.initializing'),
    t('loader.loading'),
    t('loader.decrypting'),
    t('loader.establishing'),
    t('loader.complete'),
  ]

  useEffect(() => {
    let i = 0
    const timer = setInterval(() => {
      i++
      setMsgIndex(i - 1)
      if (i >= messages.length) {
        clearInterval(timer)
        setTimeout(() => {
          setVisible(false)
          onComplete()
        }, 400)
      }
    }, 250)
    return () => clearInterval(timer)
  }, [])

  if (!visible) return null

  return (
    <div className="fixed inset-0 z-[9999] bg-dark-bg flex items-center justify-center">
      <div className="font-mono text-sm">
        {messages.map((msg, i) => (
          <div
            key={i}
            className={`${i <= msgIndex ? 'text-dark-text' : 'text-dark-text-secondary/40'}`}
          >
            &gt; {msg}
            {i === msgIndex && i < messages.length - 1 && (
              <span className="inline-block w-2 h-4 bg-dark-accent ml-1 animate-cursor" />
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

