import { useState, useEffect } from 'react'

const PHRASES = [
  'AI & DevOps Engineer',
  'Full Stack Developer',
  'Security Researcher',
  'Open Source Enthusiast',
  'System Architect',
]

export default function Typewriter({ className = '' }) {
  const [text, setText] = useState('')
  const [phraseIdx, setPhraseIdx] = useState(0)
  const [isDeleting, setIsDeleting] = useState(false)

  useEffect(() => {
    const current = PHRASES[phraseIdx]
    let timer

    if (!isDeleting && text === current) {
      timer = setTimeout(() => setIsDeleting(true), 2200)
      return () => clearTimeout(timer)
    }

    if (isDeleting && text === '') {
      timer = setTimeout(() => {
        setIsDeleting(false)
        setPhraseIdx((i) => (i + 1) % PHRASES.length)
      }, 300)
      return () => clearTimeout(timer)
    }

    timer = setTimeout(
      () => {
        setText(
          isDeleting
            ? current.substring(0, text.length - 1)
            : current.substring(0, text.length + 1),
        )
      },
      isDeleting ? 30 : 70,
    )

    return () => clearTimeout(timer)
  }, [text, isDeleting, phraseIdx])

  return (
    <span className={className}>
      {text}
      <span className="inline-block w-[2px] h-[1em] bg-dark-accent ml-0.5 animate-cursor align-middle" />
    </span>
  )
}

import { useEffect, useRef, useCallback } from 'react'

export function useCanvasLifecycle({
  canvasId,
  onFrame,
  onPause,
  onResume,
  idleTimeout = 3000,
  intersectionThreshold = 0,
}) {
  const rafRef = useRef(null)
  const idleRef = useRef(null)
  const isActiveRef = useRef(true)
  const isIdleRef = useRef(false)
  const lastActivityRef = useRef(Date.now())

  const pause = useCallback(() => {
    if (!isActiveRef.current) return
    isActiveRef.current = false
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current)
      rafRef.current = null
    }
    onPause?.()
  }, [onPause])

  const resume = useCallback(() => {
    if (isActiveRef.current) return
    isActiveRef.current = true
    onResume?.()
    const loop = (time) => {
      if (!isActiveRef.current) return
      onFrame?.(time)
      rafRef.current = requestAnimationFrame(loop)
    }
    rafRef.current = requestAnimationFrame(loop)
  }, [onFrame, onResume])

  const handleActivity = useCallback(() => {
    lastActivityRef.current = Date.now()
    if (isIdleRef.current) {
      isIdleRef.current = false
      resume()
    }
  }, [resume])

  useEffect(() => {
    const handleVisibility = () => {
      if (document.hidden) pause()
      else resume()
    }

    const el = document.getElementById(canvasId)
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) resume()
        else pause()
      },
      { threshold: intersectionThreshold }
    )

    if (el) observer.observe(el)

    document.addEventListener('visibilitychange', handleVisibility)
    document.addEventListener('mousemove', handleActivity)
    document.addEventListener('keydown', handleActivity)
    document.addEventListener('touchstart', handleActivity)

    resume()

    return () => {
      pause()
      observer.disconnect()
      document.removeEventListener('visibilitychange', handleVisibility)
      document.removeEventListener('mousemove', handleActivity)
      document.removeEventListener('keydown', handleActivity)
      document.removeEventListener('touchstart', handleActivity)
      clearTimeout(idleRef.current)
    }
  }, [canvasId, pause, resume, handleActivity, intersectionThreshold])

  return { pause, resume }
}

