import { useState, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { motion } from 'framer-motion'
import { certs } from '../../data/portfolio'
import BlurText from '../reactbits/BlurText'
import ImageModal from './ImageModal'
import SpotlightCard from '../reactbits/SpotlightCard'

const yearColors = {
  '2026': '#6C63FF',
  '2025': '#00D4FF',
}

function YearBadge({ year }) {
  const color = yearColors[year] || '#FF6B9D'
  return (
    <span
      className="font-mono text-[10px] uppercase tracking-wider px-2 py-0.5 rounded-full shrink-0"
      style={{
        backgroundColor: `${color}15`,
        color: color,
        border: `1px solid ${color}30`,
      }}
    >
      {year}
    </span>
  )
}

export default function Certifications() {
  const { t } = useTranslation()
  const [selected, setSelected] = useState(null)

  const grouped = useMemo(() => {
    const map = {}
    certs.forEach((cert) => {
      const key = cert.year || 'Other'
      if (!map[key]) map[key] = []
      map[key].push(cert)
    })
    return Object.entries(map).sort(([a], [b]) => Number(b) - Number(a))
  }, [])

  return (
    <section id="certifications" className="relative py-24 overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-b from-dark-pink/[0.02] via-transparent to-dark-accent/[0.02] pointer-events-none" />

      <div className="max-w-5xl mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-100px' }}
          transition={{ duration: 0.6 }}
          className="mb-12"
        >
          <p className="font-mono text-xs text-dark-cyan tracking-[0.3em] mb-2 uppercase">
            {'<'} {t('certifications.subtitle')} {'/>'}
          </p>
          <BlurText
            text={t('certifications.title')}
            animateBy="words"
            direction="left"
            className="font-display text-3xl md:text-5xl font-bold uppercase"
            as="h2"
          />
        </motion.div>

        {grouped.map(([year, items], gi) => (
          <div key={year} className="mb-8 last:mb-0">
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.4 }}
              className="flex items-center gap-3 mb-4"
            >
              <span
                className="font-mono text-sm font-bold tracking-widest"
                style={{ color: yearColors[year] || '#FF6B9D' }}
              >
                {year}
              </span>
              <div className="h-[1px] flex-1" style={{
                background: `linear-gradient(90deg, ${yearColors[year] || '#FF6B9D'}40, transparent)`,
              }} />
            </motion.div>

            <div className="space-y-2">
              {items.map((cert, i) => (
                <motion.div
                  key={`${year}-${i}`}
                  initial={{ opacity: 0, x: -20 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  viewport={{ once: true, margin: '-50px' }}
                  transition={{ duration: 0.4, delay: i * 0.04 }}
                >
                  <SpotlightCard
                    spotlightColor="rgba(108, 99, 255, 0.12)"
                    className="group flex items-center justify-between py-3 px-5 rounded-lg border border-dark-border/30 bg-dark-surface/20 hover:border-dark-accent/30 transition-all duration-300 cursor-pointer"
                    onClick={() => setSelected(cert)}
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <motion.span
                        initial={{ scale: 0 }}
                        whileInView={{ scale: 1 }}
                        viewport={{ once: true }}
                        transition={{ delay: i * 0.04 + 0.1, type: 'spring' }}
                        className="w-6 h-6 rounded-full bg-dark-accent/15 flex items-center justify-center text-dark-cyan text-xs shrink-0 group-hover:bg-dark-accent/25 transition-all duration-300"
                      >
                        <motion.svg
                          initial={{ pathLength: 0 }}
                          whileInView={{ pathLength: 1 }}
                          viewport={{ once: true }}
                          transition={{ delay: i * 0.04 + 0.2, duration: 0.4 }}
                          width="12" height="12" viewBox="0 0 12 12" fill="none"
                          stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"
                        >
                          <path d="M2.5 6l2.5 2.5 5-5" />
                        </motion.svg>
                      </motion.span>
                      <span className="text-sm text-dark-text truncate">{cert.name}</span>
                    </div>
                    <div className="flex items-center gap-3 shrink-0 ml-3">
                      <span className="font-mono text-[10px] text-dark-text-secondary hidden sm:block">
                        {cert.issuer}
                      </span>
                      <YearBadge year={year} />
                    </div>
                  </SpotlightCard>
                </motion.div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <ImageModal
        open={!!selected}
        src={selected?.image}
        title={selected?.name}
        onClose={() => setSelected(null)}
      />
    </section>
  )
}

import { useEffect, useRef } from 'react'

export default function SplashCursor() {
  const canvasRef = useRef()

  useEffect(() => {
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    let animId
    let drops = []
    let mouse = { x: -100, y: -100, prevX: -100, prevY: -100 }

    const resize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }

    resize()
    window.addEventListener('resize', resize)

    const addDrop = (x, y) => {
      for (let i = 0; i < 3; i++) {
        drops.push({
          x: x + (Math.random() - 0.5) * 10,
          y: y + (Math.random() - 0.5) * 10,
          vx: (Math.random() - 0.5) * 2,
          vy: (Math.random() - 0.5) * 2,
          size: Math.random() * 15 + 5,
          life: 1,
          color: ['#6C63FF', '#00D4FF', '#FF6B9D'][Math.floor(Math.random() * 3)],
        })
      }
    }

    let dropInterval = null

    const onMouse = (e) => {
      mouse.prevX = mouse.x
      mouse.prevY = mouse.y
      mouse.x = e.clientX
      mouse.y = e.clientY
      const dx = mouse.x - mouse.prevX
      const dy = mouse.y - mouse.prevY
      const speed = Math.sqrt(dx * dx + dy * dy)
      if (speed > 2) {
        addDrop(mouse.x, mouse.y)
      }
    }

    const onTouch = (e) => {
      const t = e.touches[0]
      if (!t) return
      mouse.x = t.clientX
      mouse.y = t.clientY
      addDrop(mouse.x, mouse.y)
    }

    window.addEventListener('mousemove', onMouse)
    window.addEventListener('touchmove', onTouch)

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height)

      drops = drops.filter((d) => d.life > 0)

      drops.forEach((d) => {
        d.x += d.vx
        d.y += d.vy
        d.life -= 0.015
        d.size *= 0.995

        const alpha = d.life * 0.5
        const gradient = ctx.createRadialGradient(d.x, d.y, 0, d.x, d.y, d.size)
        gradient.addColorStop(0, d.color + Math.round(alpha * 255).toString(16).padStart(2, '0'))
        gradient.addColorStop(0.5, d.color + Math.round(alpha * 0.3 * 255).toString(16).padStart(2, '0'))
        gradient.addColorStop(1, d.color + '00')

        ctx.beginPath()
        ctx.arc(d.x, d.y, d.size, 0, Math.PI * 2)
        ctx.fillStyle = gradient
        ctx.fill()

        ctx.shadowBlur = 10
        ctx.shadowColor = d.color
      })

      ctx.shadowBlur = 0

      drops.forEach((a, i) => {
        drops.slice(i + 1).forEach((b) => {
          const dx = a.x - b.x
          const dy = a.y - b.y
          const dist = Math.sqrt(dx * dx + dy * dy)
          if (dist < 60) {
            ctx.beginPath()
            ctx.moveTo(a.x, a.y)
            ctx.lineTo(b.x, b.y)
            ctx.strokeStyle = `rgba(108, 99, 255, ${(1 - dist / 60) * 0.15})`
            ctx.lineWidth = 0.5
            ctx.stroke()
          }
        })
      })

      animId = requestAnimationFrame(animate)
    }

    animate()

    return () => {
      cancelAnimationFrame(animId)
      window.removeEventListener('resize', resize)
      window.removeEventListener('mousemove', onMouse)
      window.removeEventListener('touchmove', onTouch)
    }
  }, [])

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        zIndex: 9999,
        pointerEvents: 'none',
      }}
    />
  )
}

